import sys

def main():
    data = sys.stdin.buffer.read().split()
    if len(data) < 2:
        return
    m = int(data[0])
    n = int(data[1])

    is_prime = bytearray(b'\x01') * (n + 1)
    if n >= 0:
        is_prime[0] = 0
    if n >= 1:
        is_prime[1] = 0

    i = 2
    while i * i <= n:
        if is_prime[i]:
            is_prime[i * i:n + 1:i] = b'\x00' * (((n - i * i) // i) + 1)
        i += 1

    out = '\n'.join(str(x) for x in range(m, n + 1) if is_prime[x])
    sys.stdout.write(out)
    if out:
        sys.stdout.write('\n')

if __name__ == "__main__":
    main()
